describe('Cancel In-Progress Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully cancel an in-progress upload', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/uploads/start').as('uploadStart');
    // Trigger the upload button
    cy.get('[data-testid="upload-button"]').click();
    cy.wait('@uploadStart');

    // Verify upload is in progress
    cy.get('[data-testid="upload-progress-bar"]').should('be.visible');
    cy.get('[data-testid="upload-progress-percentage"]').should('contain', '50%');

    // Click cancel button
    cy.get('[data-testid="cancel-upload-button"]').click();

    // Verify cancel button is disabled after click
    cy.get('[data-testid="cancel-upload-button"]').should('be.disabled');

    // Verify upload was canceled
    cy.get('[data-testid="upload-status"]').should('contain', 'Upload canceled');
    cy.get('[data-testid="upload-status"]').should('not.contain', 'In progress');

    // Verify no upload data is sent
    cy.intercept('POST', '/api/uploads/start').as('uploadStart');
    cy.wait('@uploadStart');
    cy.get('@uploadStart').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should not allow canceling an already completed upload', () => {
    // Trigger the upload button
    cy.get('[data-testid="upload-button"]').click();
    cy.wait('@uploadStart');

    // Verify upload is in progress
    cy.get('[data-testid="upload-progress-bar"]').should('be.visible');

    // Click cancel button
    cy.get('[data-testid="cancel-upload-button"]').click();

    // Verify cancel button is disabled
    cy.get('[data-testid="cancel-upload-button"]').should('be.disabled');

    // Verify upload was not canceled (status should remain unchanged)
    cy.get('[data-testid="upload-status"]').should('contain', 'In progress');

    // Verify no error message is displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify upload was completed successfully
    cy.get('[data-testid="upload-status"]').should('contain', 'Upload completed');
  });
});
